const listOperatorSecretsForUpdate = `-- name: ListOperatorSecretsForUpdate :many
SELECT id, totp_secret_enc FROM operator_accounts WHERE totp_secret_enc IS NOT NULL ORDER BY id FOR UPDATE
`

type ListOperatorSecretsForUpdateRow struct {
	ID            int64
	TotpSecretEnc []byte
}

// Key rotation: every secret, under the lock.
func (q *Queries) ListOperatorSecretsForUpdate(ctx context.Context) ([]ListOperatorSecretsForUpdateRow, error) {
	rows, err := q.db.Query(ctx, listOperatorSecretsForUpdate)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListOperatorSecretsForUpdateRow{}
	for rows.Next() {
		var i ListOperatorSecretsForUpdateRow
		if err := rows.Scan(&i.ID, &i.TotpSecretEnc); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listOperators = `-- name: ListOperators :many
SELECT a.id, a.email, a.full_name, a.password_hash, a.totp_secret_enc, a.totp_enrolled_at, a.totp_last_step, a.is_active, a.last_login_at, a.created_at, a.updated_at, (SELECT count(*) FROM operator_recovery_codes c WHERE c.operator_id = a.id AND c.used_at IS NULL)::int AS recovery_codes_left
FROM operator_accounts a ORDER BY lower(a.email)
`

type ListOperatorsRow struct {
	ID                int64
	Email             string
	FullName          string
	PasswordHash      string
	TotpSecretEnc     []byte
	TotpEnrolledAt    *time.Time
	TotpLastStep      *int64
	IsActive          bool
	LastLoginAt       *time.Time
	CreatedAt         time.Time
	UpdatedAt         time.Time
	RecoveryCodesLeft int32
}

func (q *Queries) ListOperators(ctx context.Context) ([]ListOperatorsRow, error) {
	rows, err := q.db.Query(ctx, listOperators)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListOperatorsRow{}
	for rows.Next() {
		var i ListOperatorsRow
		if err := rows.Scan(
			&i.ID,
			&i.Email,
			&i.FullName,
			&i.PasswordHash,
			&i.TotpSecretEnc,
			&i.TotpEnrolledAt,
			&i.TotpLastStep,
			&i.IsActive,
			&i.LastLoginAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RecoveryCodesLeft,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

